ExternalServiceRegistration.schema:
{
  "openapi": "3.0.0",
  "info": {
    "title": "ViaCEP",
    "version": "1.0.0",
    "description": "Consulta de endereco brasileiro por CEP (API publica ViaCEP)."
  },
  "servers": [
    {
      "url": "/"
    }
  ],
  "paths": {
    "/ws/{cep}/json/": {
      "get": {
        "operationId": "consultarCep",
        "summary": "Consulta endereco por CEP",
        "parameters": [
          {
            "name": "cep",
            "in": "path",
            "required": true,
            "description": "CEP com 8 digitos, sem traco.",
            "schema": {
              "type": "string"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Endereco encontrado.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Endereco"
                }
              }
            }
          }
        }
      }
    }
  },
  "components": {
    "schemas": {
      "Endereco": {
        "type": "object",
        "properties": {
          "cep": {
            "type": "string"
          },
          "logradouro": {
            "type": "string"
          },
          "complemento": {
            "type": "string"
          },
          "bairro": {
            "type": "string"
          },
          "localidade": {
            "type": "string"
          },
          "uf": {
            "type": "string"
          },
          "ibge": {
            "type": "string"
          },
          "ddd": {
            "type": "string"
          },
          "erro": {
            "type": "string"
          }
        }
      }
    }
  }
}
